function renderOperationalHistory(){
  const page=$('calls');if(!page)return;
  let panel=$('operationalHistoryPanel');
  if(!panel){panel=document.createElement('div');panel.id='operationalHistoryPanel';panel.className='card section';page.appendChild(panel)}
  const calls=(mgmt.calls||[]).filter(c=>c.testMode!==true).slice(0,20);
  panel.innerHTML=`<div class="head"><div><h3>Histórico operacional das corridas</h3><p>Cada mudança recebida no WhatsApp fica vinculada ao chamado.</p></div></div><div class="events section">${calls.length?calls.map(c=>{
    const events=Array.isArray(c.operationalTimeline)?c.operationalTimeline:[];
    const checklist=Array.isArray(c.evidenceChecklist)?c.evidenceChecklist:[];
    const pending=checklist.filter(x=>x.done!==true).length;
    const evidenceText=pending?` · ${pending} evidência(s) pendente(s)`:c.evidenceComplete===true?' · evidências concluídas':checklist.length?' · evidências em conferência':' · sem checklist cadastrado';
    return`<div class="event"><div class="head"><div><b>${esc(c.vehicle||'Chamado')} · ${esc(c.client||c.insurer||'')}</b><p>${esc(c.operationalPhase||c.status||'novo').replaceAll('_',' ')}</p></div>${tag(c.status||'novo')}</div><div class="small">${esc(c.origin||'Origem não informada')} → ${esc(c.destination||'Destino não informado')}</div><div class="small section">${events.length} registro(s)${evidenceText}</div>${events.slice(-8).reverse().map(e=>`<div class="small">${date(e.at)} · <b>${esc(e.type||'atualização').replaceAll('_',' ')}</b>${e.text?` · ${esc(e.text).slice(0,160)}`:''}</div>`).join('')}</div>`
  }).join(''):'<div class="empty">Nenhum histórico operacional registrado.</div>'}</div>`
}
function renderManagement(){const calls=mgmt.calls||[],fin=mgmt.finance||[],clients=mgmt.clients||[],fleet=mgmt.fleet||[];const revenue=fin.filter(x=>x.type==='receita'&&x.status==='pago').reduce((a,x)=>a+Number(x.amount||0),0),expense=fin.filter(x=>x.type==='despesa'&&x.status==='pago').reduce((a,x)=>a+Number(x.amount||0),0),pending=fin.filter(x=>x.type==='receita'&&x.status!=='pago').reduce((a,x)=>a+Number(x.amount||0),0);$('callsKpi').textContent=calls.filter(x=>x.status!=='concluido'&&x.status!=='cancelado').length;$('revenueKpi').textContent=money(revenue);$('balanceKpi').textContent=money(revenue-expense);$('pendingKpi').textContent=money(pending);$('callsTable').innerHTML=calls.length?calls.slice(0,20).map(c=>`<tr><td><b>${esc(c.vehicle||'Veículo')}</b><br><span class="muted">${esc(c.client||c.insurer||'')}</span></td><td>${esc(c.origin||'—')}</td><td>${esc(c.destination||'—')}</td><td>${tag(c.status||'novo')}</td><td>${money(c.value)}${c.cancellationChargeRequired?`<br><span class="tag red">Saída/deslocamento integral</span><br><span class="small">${esc(c.cancellationBillableKm??c.billableKm??c.totalKm??'—')} km · sem pagamento parcial</span>`:c.status==='cancelado'&&c.cancellationWithinFreeWindow?'<br><span class="tag green">Cancelado em até 15 min · sem cobrança</span>':c.financeReviewRequired?'<br><span class="tag red">Conferir financeiro</span>':c.estimatedTotalKm?`<br><span class="small">Estimativa ${esc(c.estimatedTotalKm)} km</span>`:''}</td><td><button class="btn small ghost" onclick="editItem('calls','${c.id}')">Editar</button></td></tr>`).join(''):'<tr><td colspan="6">Nenhum chamado cadastrado.</td></tr>';$('clientsTable').innerHTML=clients.length?clients.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone||'—')}</td><td>${esc(c.email||'—')}</td><td>${esc(c.type||'Cliente')}</td><td><button class="btn small ghost" onclick="editItem('clients','${c.id}')">Editar</button></td></tr>`).join(''):'<tr><td colspan="5">Nenhum cliente cadastrado.</td></tr>';$('financeTable').innerHTML=fin.length?fin.map(f=>`<tr><td>${date(f.dueDate||f.createdAt)}</td><td><b>${esc(f.description||'Lançamento')}</b><br><span class="muted">${esc(f.category||'')}</span></td><td>${esc(f.type||'')}</td><td class="money ${f.type==='receita'?'pos':'neg'}">${money(f.amount)}</td><td>${tag(f.status||'pendente')}</td><td><button class="btn small ghost" onclick="editItem('finance','${f.id}')">Editar</button></td></tr>`).join(''):'<tr><td colspan="6">Nenhum lançamento.</td></tr>';$('fleetCards').innerHTML=fleet.length?fleet.map(v=>`<div class="card"><div class="head"><div><h3>${esc(v.name||v.plate)}</h3><p>${esc(v.plate||'')}</p></div>${tag(v.status||'disponivel')}</div><div class="kpi-line"><span>Motorista</span><b>${esc(v.driver||'Não definido')}</b></div><div class="kpi-line"><span>Observações</span><b>${esc(v.notes||'—')}</b></div><button class="btn secondary small section" onclick="editItem('fleet','${v.id}')">Editar veículo</button></div>`).join(''):'<div class="empty">Nenhum veículo.</div>';$('automationList').innerHTML=(mgmt.automations||[]).map(a=>`<div class="switch"><div><b>${esc(a.name)}</b><div class="muted">${esc(a.trigger||'regra')} → ${esc(a.action||'ação')}</div></div><input type="checkbox" ${a.enabled!==false?'checked':''} onchange="toggleAutomation('${a.id}',this.checked)"></div>`).join('');$('companyNameDisplay').textContent=mgmt.company?.name||'Central Guincho';renderOps();renderFinanceSummary()}
function renderOps(){const open=(mgmt.calls||[]).filter(x=>!['concluido','cancelado'].includes(x.status));$('opsList').innerHTML=open.length?open.map(c=>`<div class="event"><div class="head"><div><b>${esc(c.vehicle||'Chamado')}</b><p>${esc(c.client||c.insurer||'')}</p></div>${tag(c.status||'novo')}</div><div class="small">${esc(c.origin||'Origem não informada')} → ${esc(c.destination||'Destino não informado')}</div></div>`).join(''):'<div class="empty">Nenhum chamado em andamento.</div>'}
function renderFinanceSummary(){const f=mgmt.finance||[];const r=f.filter(x=>x.type==='receita').reduce((a,x)=>a+Number(x.amount||0),0),d=f.filter(x=>x.type==='despesa').reduce((a,x)=>a+Number(x.amount||0),0);$('financeRevenue').textContent=money(r);$('financeExpense').textContent=money(d);$('financeResult').textContent=money(r-d)}
