const modal=$('modal');function openModal(title,html,onSave){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;modal.classList.add('open');$('modalSave').onclick=onSave}function closeModal(){modal.classList.remove('open')}$('modalClose').onclick=closeModal;modal.onclick=e=>{if(e.target===modal)closeModal()};
function field(label,name,value='',type='text',opts=''){if(type==='select')return `<div class="field"><label>${label}</label><select name="${name}">${opts}</select></div>`;return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}"></div>`}
window.newItem=collection=>editItem(collection,null);window.editItem=(collection,id)=>{const item=(mgmt[collection]||[]).find(x=>x.id===id)||{};let html='';if(collection==='calls')html=`<div class="form-grid">${field('Veículo','vehicle',item.vehicle)}${field('Cliente/Seguradora','client',item.client)}${field('Origem','origin',item.origin)}${field('Destino','destination',item.destination)}${field('Valor','value',item.value,'number')}${field('Status','status','', 'select', ['novo','cotacao','aguardando_aprovacao','autorizado','agendado','a_caminho','em_atendimento','concluido','cancelado'].map(x=>`<option ${item.status===x?'selected':''} value="${x}">${x.replaceAll('_',' ')}</option>`).join(''))}</div>`;if(collection==='clients')html=`<div class="form-grid">${field('Nome','name',item.name)}${field('Telefone','phone',item.phone)}${field('E-mail','email',item.email,'email')}${field('Tipo','type',item.type||'Seguradora')}</div>`;if(collection==='finance')html=`<div class="form-grid">${field('Descrição','description',item.description)}${field('Categoria','category',item.category)}${field('Valor','amount',item.amount,'number')}${field('Vencimento','dueDate',item.dueDate,'date')}${field('Tipo','type','', 'select',`<option ${item.type==='receita'?'selected':''} value="receita">Receita</option><option ${item.type==='despesa'?'selected':''} value="despesa">Despesa</option>`)}${field('Status','status','', 'select',`<option ${item.status==='pendente'?'selected':''} value="pendente">Pendente</option><option ${item.status==='pago'?'selected':''} value="pago">Pago</option><option ${item.status==='atrasado'?'selected':''} value="atrasado">Atrasado</option>`)}</div>`;if(collection==='fleet')html=`<div class="form-grid">${field('Nome','name',item.name)}${field('Placa','plate',item.plate)}${field('Motorista','driver',item.driver)}${field('Status','status','', 'select',`<option ${item.status==='disponivel'?'selected':''} value="disponivel">Disponível</option><option ${item.status==='em_servico'?'selected':''} value="em_servico">Em serviço</option><option ${item.status==='manutencao'?'selected':''} value="manutencao">Manutenção</option>`)}${field('Observações','notes',item.notes)}</div>`;openModal((id?'Editar ':'Novo ')+({calls:'chamado',clients:'cliente',finance:'lançamento',fleet:'veículo'}[collection]||collection),html,()=>{const fd=new FormData($('modalForm'));const obj=Object.fromEntries(fd.entries());if(id)obj.id=id;if(obj.value)obj.value=Number(obj.value);if(obj.amount)obj.amount=Number(obj.amount);saveMgmt({action:'upsert',collection,item:obj})})};

let excludedAreasDraft=[];
function renderExcludedAreas(){
  const box=$('excludedAreaList');if(!box)return;
  if(!excludedAreasDraft.length){box.innerHTML='<div class="empty">Nenhuma área cadastrada.</div>';return;}
  const typeName={city:'Cidade',neighborhood:'Bairro'},scopeName={origin:'Origem',destination:'Destino',both:'Origem e destino'};
  box.innerHTML=excludedAreasDraft.map((a,i)=>`<div class="event"><div><b>${esc(typeName[a.type]||a.type)}: ${esc(a.name)}</b><small>${a.type==='neighborhood'&&a.city?esc(a.city)+' · ':''}${esc(scopeName[a.scope]||'Origem')}</small></div><button class="btn small ghost" onclick="removeExcludedArea(${i})">Remover</button></div>`).join('');
}
function syncExcludedAreaFields(){const isCity=$('excludedAreaType')?.value==='city';if($('excludedAreaCity')){$('excludedAreaCity').disabled=isCity;if(isCity)$('excludedAreaCity').value='';}}
async function loadExcludedAreas(){try{const d=await api('/api/worker/settings');excludedAreasDraft=Array.isArray(d.excludedAreas)?d.excludedAreas.map(x=>({...x})):[];if($('outOfRouteReply'))$('outOfRouteReply').value=d.outOfRouteReply||'Motorista fora de rota.';renderExcludedAreas();syncExcludedAreaFields()}catch(e){if($('excludedAreaList'))$('excludedAreaList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
window.removeExcludedArea=i=>{excludedAreasDraft.splice(i,1);renderExcludedAreas()};
$('excludedAreaType')?.addEventListener('change',syncExcludedAreaFields);
$('addExcludedArea')?.addEventListener('click',()=>{const type=$('excludedAreaType').value,name=$('excludedAreaName').value.trim(),city=$('excludedAreaCity').value.trim(),scope=$('excludedAreaScope').value;if(!name){$('excludedAreaNotice').style.display='block';$('excludedAreaNotice').className='notice bad section';$('excludedAreaNotice').textContent='Informe o nome da cidade ou do bairro.';return}excludedAreasDraft.push({type,name,city:type==='neighborhood'?city:'',scope});$('excludedAreaName').value='';$('excludedAreaCity').value='';renderExcludedAreas();$('excludedAreaNotice').style.display='none'});
$('saveExcludedAreas')?.addEventListener('click',async()=>{try{const reply=$('outOfRouteReply').value.trim()||'Motorista fora de rota.';const d=await api('/api/worker/settings',{method:'POST',body:JSON.stringify({excludedAreas:excludedAreasDraft,outOfRouteReply:reply})});excludedAreasDraft=Array.isArray(d.settings?.excludedAreas)?d.settings.excludedAreas:excludedAreasDraft;renderExcludedAreas();$('excludedAreaNotice').style.display='block';$('excludedAreaNotice').className='notice good section';$('excludedAreaNotice').textContent='Áreas fora de rota salvas para esta empresa.'}catch(e){$('excludedAreaNotice').style.display='block';$('excludedAreaNotice').className='notice bad section';$('excludedAreaNotice').textContent=e.message}});

async function loadGroups(){try{const d=await api('/api/worker/groups');$('groupList').innerHTML=(d.groups||[]).map(g=>`<label class="group"><input type="checkbox" value="${esc(g.id)}" ${g.selected?'checked':''}><div><b>${esc(g.name||'Grupo')}</b><div class="small">${esc(g.id)}</div></div></label>`).join('')||'<div class="empty">Nenhum grupo.</div>'}catch(e){$('groupList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function commercialRuleHtml(k){const r=(k.commercialStatus==='approved'?k.approvedCommercialRules:k.draftCommercialRules)||{};const entries=Object.entries(r.services||{}).filter(([,x])=>Number(x?.basePrice)>0);const lines=entries.map(([name,x])=>`<div class="kpi-line"><span>${esc(name.replaceAll('_',' '))}</span><b>${money(x.basePrice)} até ${esc(x.includedKm??'—')} km · ${money(x.pricePerKm)}/km</b></div>`).join('');const extras=[r.workedHour?`Hora trabalhada ${money(r.workedHour)}`:'',r.stoppedHour?`Hora parada ${money(r.stoppedHour)}`:'',r.invoiceFee?`NF ${money(r.invoiceFee)}`:'',r.tollAllowed?'Pedágio separado':''].filter(Boolean).join(' · ');return `${lines||'<div class="muted">Nenhuma tabela estruturada detectada.</div>'}${extras?`<div class="small section">${esc(extras)}</div>`:''}`}
async function loadKnowledge(){if(!$('knowledgeList'))return;try{const [gd,kd]=await Promise.all([api('/api/worker/groups'),api('/api/worker/group-knowledge')]);const selected=new Set((gd.groups||[]).filter(g=>g.selected).map(g=>g.id));const items=(kd.groups||[]).filter(k=>selected.has(k.groupId));$('knowledgeList').innerHTML=items.length?items.map(k=>{const approved=k.commercialStatus==='approved',review=k.commercialStatus==='review_required',detected=!!k.draftCommercialRules?.detected;const status=approved?'Tabela aprovada':review?'Revisar tabela':detected?'Tabela detectada':'Sem tabela detectada';const statusClass=approved?'green':review?'yellow':'yellow';const versions=(k.commercialVersions||[]).length;return `<div class="card"><div class="head"><div><h3>${esc(k.name||'Grupo')}</h3><p>${esc((k.description||'Sem descrição').slice(0,180))}</p></div><span class="tag ${statusClass}">${status}</span></div>${commercialRuleHtml(k)}<div class="kpi-line section"><span>Exemplos humanos aprendidos</span><b>${(k.examples||[]).length}</b></div><div class="kpi-line"><span>Versões comerciais preservadas</span><b>${versions}</b></div><div class="actions section"><button class="btn secondary small" onclick="importGroupHistory('${esc(k.groupId)}')">Importar histórico</button><button class="btn secondary small" onclick="refreshGroupKnowledge('${esc(k.groupId)}')">Ler descrição</button>${detected&&!approved?`<button class="btn small" onclick="approveGroupCommercial('${esc(k.groupId)}','${esc(k.name||'grupo')}')">Aprovar tabela</button>`:''}</div></div>`}).join(''):'<div class="empty">Selecione e salve ao menos um grupo autorizado para iniciar o aprendizado.</div>'}catch(e){$('knowledgeList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
window.refreshGroupKnowledge=async id=>{await api('/api/worker/group-knowledge',{method:'POST',body:JSON.stringify({groupId:id,action:'refresh'})});await loadKnowledge()};
window.importGroupHistory=async id=>{if(!confirm('Importar até 1.000 mensagens disponíveis deste grupo para aprendizado? O robô não responderá mensagens antigas.'))return;const d=await api('/api/worker/learning-import',{method:'POST',body:JSON.stringify({groupId:id,limit:1000})});alert(`${d.imported||0} mensagens novas importadas.`);await loadKnowledge()};
window.approveGroupCommercial=async(id,name)=>{if(!confirm(`Aprovar a tabela comercial atualmente detectada em ${name}? Ela poderá ser usada em cotações e conferências financeiras.`))return;await api('/api/worker/group-knowledge',{method:'POST',body:JSON.stringify({groupId:id,action:'approve-commercial'})});await loadKnowledge()};
$('saveGroups').onclick=async()=>{const ids=$$('#groupList input:checked').map(x=>x.value);await api('/api/worker/groups',{method:'POST',body:JSON.stringify({groupIds:ids})});await loadStatus();await loadKnowledge();alert('Grupos salvos')};$('syncGroups').onclick=async()=>{await loadGroups();await loadKnowledge()};if($('refreshKnowledge'))$('refreshKnowledge').onclick=loadKnowledge;
async function loadTracker(){try{const d=await api('/api/worker/tracker');$('pairCode').textContent=d.pairCode||'--------';$('trackerNotice').textContent=d.connected?`Agente conectado · leitura há ${d.ageSeconds||0}s`:'Aguardando agente';$('trackerNotice').className='notice '+(d.connected?'good':'warn');const x=d.lastLocation||{};$('trackerLocation').innerHTML=`<div><span>Placa</span><b>${esc(x.plate||'—')}</b></div><div><span>Ignição</span><b>${esc(x.ignition||'—')}</b></div><div><span>Velocidade</span><b>${esc(x.speedKph??'—')} km/h</b></div><div><span>Bateria</span><b>${esc(x.batteryVoltage??'—')} V</b></div><div class="full"><span>Endereço atual</span><b>${esc(x.address||'—')}</b></div>`}catch(e){$('trackerNotice').textContent=e.message}}
$('rotatePair').onclick=async()=>{await api('/api/worker/tracker',{method:'POST',body:JSON.stringify({action:'rotate_pair_code'})});loadTracker()};$('refreshTracker').onclick=loadTracker;
async function loadSettings(){try{const d=await api('/api/worker/settings');$('aiEnabled').checked=!!d.aiEnabled;$('replyEvery').checked=d.replyEveryMessage!==false;$('human').checked=!!d.humanTakeover;$('aiModel').value=d.aiModel||'';$('aiInstructions').value=d.aiInstructions||'';$('aiNotice').textContent=d.apiKeyConfigured?'IA configurada e pronta.':'Credencial da IA não configurada.';$('aiNotice').className='notice '+(d.apiKeyConfigured?'good':'warn')}catch(e){$('aiNotice').textContent=e.message}}
$('saveAi').onclick=async()=>{await api('/api/worker/settings',{method:'POST',body:JSON.stringify({aiEnabled:$('aiEnabled').checked,replyEveryMessage:$('replyEvery').checked,humanTakeover:$('human').checked,aiModel:$('aiModel').value,aiInstructions:$('aiInstructions').value})});$('aiNotice').textContent='Configurações salvas.';$('aiNotice').className='notice good'};$('refreshWa').onclick=loadStatus;
$('companyBtn').onclick=()=>{const c=mgmt.company||{};openModal('Dados da empresa',`<div class="form-grid">${field('Nome','name',c.name)}${field('CNPJ/CPF','document',c.document)}${field('Telefone','phone',c.phone)}${field('E-mail','email',c.email,'email')}</div>`,()=>{const obj=Object.fromEntries(new FormData($('modalForm')).entries());saveMgmt({action:'replace_company',item:obj})})};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('installBtn')?.classList.remove('hidden')});$('installBtn').onclick=async()=>{if(deferredPrompt){deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null}else alert('No iPhone: Compartilhar → Adicionar à Tela de Início.')};
if($('refreshHelp'))$('refreshHelp').onclick=loadHelp;
if($('dismissOnboarding'))$('dismissOnboarding').onclick=()=>{localStorage.setItem('bg-onboarding-done','1');$('onboardingCard')?.remove()};
if(localStorage.getItem('bg-onboarding-done')==='1')$('onboardingCard')?.remove();
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(reg=>reg.update()).catch(console.error));
function ensureTestCenterUI(){
  if($('tests'))return;
  const style=document.createElement('style');style.textContent='.test-scenarios{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.test-scenario{display:flex;gap:11px;align-items:center;background:#11181e;border:1px solid #28353f;border-radius:13px;padding:13px}.test-scenario .scenario-mark{color:var(--brand);font-size:20px}.test-scenario span{display:grid;gap:3px}.test-scenario small{color:var(--muted)}.test-step{padding:9px 0;border-top:1px solid #28343d}.test-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:700px){.test-scenarios{grid-template-columns:1fr}}';document.head.appendChild(style);
  const nav=document.querySelector('.sidebar .nav');if(nav){const b=document.createElement('button');b.dataset.page='tests';b.innerHTML='<span class="ico">✓</span>Central de testes';b.onclick=()=>showPage('tests');const help=[...nav.children].find(x=>x.dataset.page==='help');nav.insertBefore(b,help||null)}
  const section=document.createElement('section');section.id='tests';section.className='page';section.innerHTML=`<div class="head"><div><h2>Central de testes</h2><p>O robô reproduz sozinho todas as situações e confere as respostas.</p></div><button class="btn secondary" id="refreshTests">Atualizar</button></div><div class="notice warn">Proteção ativa: mensagens somente no grupo <b>Tests guincho</b>. Corridas simuladas não entram no financeiro nem na folha do motorista.</div><div class="grid2 section"><div class="card"><div class="head"><div><h3>Segundo WhatsApp</h3><p id="testSimulatorText">Desconectado</p></div><span id="testSimulatorStatus" class="tag yellow">desconectado</span></div><div id="testSimulatorQr" class="qr"><div class="empty">Clique em conectar para gerar o QR Code.</div></div><div class="actions section"><button class="btn" id="connectSimulator">Conectar segundo número</button><button class="btn secondary" id="disconnectSimulator">Desconectar</button></div></div><div class="card"><h3>Teste automático completo</h3><p class="muted section">Um clique executa todas as conversas reais e todas as regras internas, na ordem correta.</p><div class="metrics test-metrics section"><div class="metric-card"><span>Aprovados</span><strong id="testPassed">0</strong></div><div class="metric-card"><span>Falhas</span><strong id="testFailed">0</strong></div><div class="metric-card"><span>Pendentes</span><strong id="testPending">0</strong></div></div><div id="testRunNotice" class="notice section">Nenhum teste em execução.</div><div class="actions section"><button class="btn" id="runAllTests">Iniciar teste completo automático</button><button class="btn danger" id="stopTests">Parada de emergência</button></div></div></div><div class="card section"><div class="head"><div><h3>Fluxos incluídos</h3><p>Todos serão executados automaticamente; não é necessário selecionar.</p></div></div><div id="testScenarios" class="test-scenarios"><div class="empty">Carregando...</div></div></div><div class="card section"><h3>Resultado detalhado</h3><div id="testResults" class="events section"><div class="empty">Execute uma bateria para ver os resultados.</div></div></div>`;document.querySelector('.main').appendChild(section);
  $('refreshTests').onclick=loadTestCenter;$('connectSimulator').onclick=()=>testCenterAction('connect');$('disconnectSimulator').onclick=()=>testCenterAction('disconnect');$('stopTests').onclick=()=>testCenterAction('stop');$('runAllTests').onclick=runAllTests;
}
let testCenterCache={scenarios:[],simulator:{},history:[]},testCenterPoll=null;
function testStatusTag(status){const c=status==='passed'?'green':status==='failed'?'red':'yellow';return`<span class="tag ${c}">${esc(status||'pendente')}</span>`}
function renderTestCenter(){const d=testCenterCache,s=d.simulator||{},run=d.currentRun||d.history?.[0];$('testSimulatorStatus').textContent=s.status||'desconectado';$('testSimulatorStatus').className='tag '+(s.status==='pronto'?'green':s.status==='erro'?'red':'yellow');$('testSimulatorText').textContent=s.error||({pronto:'Pronto para simular',qr:'Escaneie o QR com o segundo número',iniciando:'Iniciando sessão segura...'}[s.status]||'Desconectado');$('testSimulatorQr').innerHTML=s.qrDataUrl?`<img src="${s.qrDataUrl}" alt="QR Code do segundo WhatsApp">`:'<div class="empty">'+(s.status==='pronto'?'Segundo número conectado.':'Clique em conectar para gerar o QR Code.')+'</div>';
  $('testScenarios').innerHTML=(d.scenarios||[]).map(x=>`<div class="test-scenario"><span class="scenario-mark">✓</span><span><b>${esc(x.name)}</b><small>${esc(x.category)} · ${x.mode==='whatsapp'?'WhatsApp real':'Regra interna'}</small></span></div>`).join('')||'<div class="empty">Nenhum cenário.</div>';
  const totals=run?.totals||{};$('testPassed').textContent=totals.passed||0;$('testFailed').textContent=totals.failed||0;$('testPending').textContent=Math.max(0,(totals.scenarios||0)-(totals.passed||0)-(totals.failed||0)-(totals.skipped||0));$('testRunNotice').textContent=run?(run.error||`Bateria ${run.status}: ${totals.passed||0} aprovados e ${totals.failed||0} falhas.`):'Nenhum teste em execução.';$('testRunNotice').className='notice section '+(run?.status==='completed'&&!(totals.failed)?'good':run?.status==='failed'||totals.failed?'bad':'warn');
  $('testResults').innerHTML=run?.results?.length?run.results.map(x=>`<div class="event"><div class="head"><div><b>${esc(x.name)}</b><div class="small">${esc(x.category)} · ${esc(x.mode)}</div></div>${testStatusTag(x.status)}</div>${x.error?`<div class="notice bad">${esc(x.error)}</div>`:''}${(x.steps||[]).map(step=>`<div class="test-step"><b>${step.passed?'✓':'✕'} ${esc(step.sent||step.expected||'Validação')}</b>${step.response?`<div class="small">Resposta: ${esc(step.response)}</div>`:''}</div>`).join('')}</div>`).join(''):'<div class="empty">Execute uma bateria para ver os resultados.</div>';
  const simulatorTransitioning=['iniciando','reiniciando','autenticado','qr','reconectando'].includes(s.status);if((run?.status==='running'||simulatorTransitioning)&&!testCenterPoll)testCenterPoll=setInterval(()=>loadTestCenter().catch(()=>{}),3000);if(run?.status!=='running'&&!simulatorTransitioning&&testCenterPoll){clearInterval(testCenterPoll);testCenterPoll=null}}
async function loadTestCenter(){ensureTestCenterUI();try{testCenterCache=await api('/api/worker/test-center');renderTestCenter()}catch(e){$('testRunNotice').textContent=e.message;$('testRunNotice').className='notice bad section'}}
async function testCenterAction(action){try{await api('/api/worker/test-center',{method:'POST',body:JSON.stringify({action})});await loadTestCenter();if(action==='connect')setTimeout(loadTestCenter,2500)}catch(e){alert(e.message)}}
async function runAllTests(){try{await api('/api/worker/test-center',{method:'POST',body:JSON.stringify({action:'run_all'})});await loadTestCenter()}catch(e){alert(e.message)}}
ensureTestCenterUI();
(async()=>{showPage(localStorage.getItem('bg-page')||'dashboard');await Promise.allSettled([loadStatus(),loadManagement(),loadActivity(),loadHealth()]);setInterval(()=>loadStatus().catch(()=>{}),20000);setInterval(()=>loadActivity().catch(()=>{}),30000);setInterval(()=>loadHealth().catch(()=>{}),30000)})();

// ===== Horário de funcionamento + faturamento por grupo =====
const BG_DAY_LABELS={mon:'Segunda',tue:'Terça',wed:'Quarta',thu:'Quinta',fri:'Sexta',sat:'Sábado',sun:'Domingo'};
function ensureOperatingHoursUI(){
  if($('operatingHoursConfig'))return;
  const page=$('automations');if(!page)return;
  page.insertAdjacentHTML('beforeend',`<div id="operatingHoursConfig" class="card section"><div class="head"><div><h3>Horário de funcionamento</h3><p>Fora desses períodos o robô responde “Motorista fora de rota.”</p></div><button class="btn" id="saveOperatingHours">Salvar horário</button></div><div class="switch section"><div><b>Usar horário de funcionamento</b><div class="muted">Desative para funcionar 24 horas.</div></div><input id="operatingHoursEnabled" type="checkbox"></div><div class="grid2 section"><div class="field"><label>Fuso horário</label><input id="operatingTimezone" value="America/Sao_Paulo"></div><div class="field"><label>Endereço da base do caminhão</label><input id="operationalBaseAddress" placeholder="Rua, número, bairro, cidade - UF"></div></div><div class="field section"><label>Resposta fora do horário</label><input id="outOfHoursReply" value="Motorista fora de rota."></div><div class="table-wrap section"><table class="table"><thead><tr><th>Dia</th><th>Funciona</th><th>Períodos</th></tr></thead><tbody id="operatingScheduleRows"></tbody></table></div><div class="notice section">Para horário de almoço, use dois períodos. Ex.: <b>08:00-12:00, 13:00-18:00</b>.</div><div id="operatingHoursNotice" class="notice section" style="display:none"></div></div>`);
  $('saveOperatingHours').onclick=saveOperatingHours;
}
function intervalsText(day){return(day?.intervals||[]).map(x=>`${x.start}-${x.end}`).join(', ')}
function parseIntervalsText(value){return String(value||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>{const m=x.match(/^(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})$/);return m?{start:m[1].padStart(5,'0'),end:m[2].padStart(5,'0')}:null}).filter(Boolean)}
async function loadOperatingHours(){
  ensureOperatingHoursUI();try{const s=await api('/api/worker/settings');$('operatingHoursEnabled').checked=s.operatingHoursEnabled===true;$('operatingTimezone').value=s.operatingTimezone||'America/Sao_Paulo';$('operationalBaseAddress').value=s.operationalBaseAddress||'';$('outOfHoursReply').value=s.outOfHoursReply||'Motorista fora de rota.';const schedule=s.weeklySchedule||{};$('operatingScheduleRows').innerHTML=Object.entries(BG_DAY_LABELS).map(([key,label])=>{const day=schedule[key]||{};return`<tr data-operating-day="${key}"><td><b>${label}</b></td><td><input class="day-enabled" type="checkbox" ${day.enabled?'checked':''}></td><td><input class="day-intervals" value="${esc(intervalsText(day))}" placeholder="08:00-12:00, 13:00-18:00"></td></tr>`}).join('')}catch(e){console.error(e)}}
async function saveOperatingHours(){
  const weeklySchedule={};$$('[data-operating-day]').forEach(row=>{const key=row.dataset.operatingDay;weeklySchedule[key]={enabled:row.querySelector('.day-enabled').checked,intervals:parseIntervalsText(row.querySelector('.day-intervals').value)}});const notice=$('operatingHoursNotice');try{await api('/api/worker/settings',{method:'POST',body:JSON.stringify({operatingHoursEnabled:$('operatingHoursEnabled').checked,operatingTimezone:$('operatingTimezone').value,operationalBaseAddress:$('operationalBaseAddress').value,outOfHoursReply:$('outOfHoursReply').value,weeklySchedule})});notice.style.display='block';notice.className='notice good section';notice.textContent='Horário salvo. A regra já vale para esta empresa.'}catch(e){notice.style.display='block';notice.className='notice bad section';notice.textContent='Erro ao salvar: '+e.message}}

function ensureBillingFinanceUILegacy(){
  if($('billingFinanceConfig'))return;const page=$('finance');if(!page)return;
  page.insertAdjacentHTML('beforeend',`<div id="billingFinanceConfig" class="section"><div class="card"><div class="head"><div><h3>Faturamento por seguradora/grupo</h3><p>Ciclos de fechamento, planilha, nota fiscal e recebimento.</p></div><button class="btn secondary" id="refreshBilling">Atualizar</button></div><div class="notice warn section">O calendário só automatiza recebimentos depois de ser revisado e aprovado para aquele grupo.</div><div id="billingProfilesList" class="grid2 section"></div></div><div class="card section"><div class="head"><div><h3>Fechamentos e pagamentos</h3><p>Viagens agrupadas automaticamente por período.</p></div></div><div class="table-wrap section"><table class="table"><thead><tr><th>Grupo</th><th>Período</th><th>Viagens/KM</th><th>Total</th><th>Planilha</th><th>Pagamento</th><th>Status</th><th></th></tr></thead><tbody id="billingBatchesTable"></tbody></table></div></div></div>`);$('refreshBilling').onclick=loadBillingFinance;
}
let billingCache={profiles:[],batches:[]};
const billingModeLabel={monthly:'Mensal',semimonthly:'Quinzenal',per_call:'À vista / por chamado',dynamic_per_call:'À vista ou faturado por chamado',manual:'Manual'};
async function loadBillingFinance(){ensureBillingFinanceUI();try{billingCache=await api('/api/worker/billing');renderBillingFinance()}catch(e){console.error(e)}}
function renderBillingFinanceLegacy(){const profiles=billingCache.profiles||[],batches=billingCache.batches||[];$('billingProfilesList').innerHTML=profiles.length?profiles.map(p=>`<div class="card"><div class="head"><div><h3>${esc(p.groupName||'Grupo')}</h3><p>${esc(billingModeLabel[p.paymentMode]||p.paymentMode)}</p></div>${tag(p.status==='approved'?'Aprovado':'Revisar')}</div><div class="small">Rota: ${p.routeBasis==='truck_origin_destination_base'?'Caminhão → origem → destino → base':esc(p.routeBasis)}</div>${p.sourceNote?`<p class="muted section">${esc(p.sourceNote)}</p>`:''}<div class="actions section"><button class="btn secondary small" onclick="editBillingProfile('${p.groupId}')">Configurar</button>${p.status!=='approved'?`<button class="btn small" onclick="approveBillingProfile('${p.groupId}')">Aprovar</button>`:''}</div></div>`).join(''):'<div class="empty">Os grupos aparecerão aqui depois de sincronizados.</div>';$('billingBatchesTable').innerHTML=batches.length?batches.map(b=>`<tr><td><b>${esc(b.groupName||'Grupo')}</b></td><td>${esc(b.periodStart||'—')}<br><span class="muted">até ${esc(b.periodEnd||'—')}</span></td><td>${b.callCount||0} viagens<br><span class="muted">${Number(b.totalKm||0).toLocaleString('pt-BR')} km</span></td><td>${money(b.totalAmount)}</td><td>${date(b.statementDue)}</td><td>${date(b.paymentDue)}</td><td>${tag(String(b.status||'accumulating').replaceAll('_',' '))}</td><td><div class="actions"><button class="btn ghost small" onclick="downloadBillingBatch('${b.id}')">Planilha</button>${!b.statementSentAt?`<button class="btn ghost small" onclick="billingBatchAction('${b.id}','statement_sent')">Enviada</button>`:''}${b.statementSentAt&&!b.invoiceSentAt?`<button class="btn ghost small" onclick="billingBatchAction('${b.id}','invoice_sent')">NF enviada</button>`:''}${b.status!=='received'?`<button class="btn small" onclick="billingBatchAction('${b.id}','received')">Recebido</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="8">Nenhum fechamento criado ainda.</td></tr>'}
window.editBillingProfile=groupId=>{const p=(billingCache.profiles||[]).find(x=>x.groupId===groupId);if(!p)return;const modeOpts=Object.entries(billingModeLabel).map(([v,l])=>`<option value="${v}" ${p.paymentMode===v?'selected':''}>${l}</option>`).join('');const routeOpts=[['truck_origin_destination_base','Caminhão → origem → destino → base'],['origin_destination','Somente origem → destino'],['insurer_reported','KM informado pela seguradora'],['manual','Manual']].map(([v,l])=>`<option value="${v}" ${p.routeBasis===v?'selected':''}>${l}</option>`).join('');const cycles=(p.cycles||[]);const rows=(cycles.length?cycles:[{}]).map((c,i)=>billingCycleRow(c,i)).join('');openModal('Regra financeira — '+(p.groupName||'Grupo'),`<div class="form-grid"><div class="field"><label>Modelo de pagamento</label><select name="paymentMode">${modeOpts}</select></div><div class="field"><label>KM cobrados</label><select name="routeBasis">${routeOpts}</select></div><div class="field"><label>Base específica do grupo (opcional)</label><input name="baseAddress" value="${esc(p.baseAddress||'')}"></div><div class="field"><label>Dias para pagar (à vista)</label><input name="daysToPay" type="number" value="${Number(p.daysToPay||0)}"></div></div><h4 class="section">Ciclos de faturamento</h4><p class="muted">Use um ciclo para mensal e dois para quinzenal. Campos vazios são permitidos enquanto estiver em revisão.</p><div id="billingCyclesEditor">${rows}</div><button type="button" class="btn secondary small section" onclick="addBillingCycleRow()">+ Adicionar ciclo</button><div class="field section"><label>Observações</label><textarea name="notes">${esc(p.notes||'')}</textarea></div>`,async()=>{const f=$('modalBody');const cycles=[...f.querySelectorAll('.billing-cycle-row')].map((row,i)=>({id:row.dataset.id||`cycle-${i+1}`,statementDay:row.querySelector('[name=statementDay]').value||null,lookbackDays:row.querySelector('[name=lookbackDays]').value||null,submitWindowStartDay:row.querySelector('[name=submitWindowStartDay]').value||null,submitWindowEndDay:row.querySelector('[name=submitWindowEndDay]').value||null,invoiceDeadlineDay:row.querySelector('[name=invoiceDeadlineDay]').value||null,paymentDay:row.querySelector('[name=paymentDay]').value||null,paymentMonthOffset:row.querySelector('[name=paymentMonthOffset]').value||0}));await api('/api/worker/billing',{method:'POST',body:JSON.stringify({action:'save_profile',profile:{...p,status:'needs_review',paymentMode:f.querySelector('[name=paymentMode]').value,routeBasis:f.querySelector('[name=routeBasis]').value,baseAddress:f.querySelector('[name=baseAddress]').value,daysToPay:Number(f.querySelector('[name=daysToPay]').value||0),cycles,notes:f.querySelector('[name=notes]').value}})});closeModal();await loadBillingFinance()})};
function billingCycleRow(c={},i=0){return`<div class="card section billing-cycle-row" data-id="${esc(c.id||`cycle-${i+1}`)}"><div class="form-grid"><div class="field"><label>Dia da planilha</label><input name="statementDay" type="number" min="1" max="31" value="${c.statementDay??''}"></div><div class="field"><label>Período anterior (dias)</label><input name="lookbackDays" type="number" value="${c.lookbackDays??''}"></div><div class="field"><label>Janela envio: início</label><input name="submitWindowStartDay" type="number" min="1" max="31" value="${c.submitWindowStartDay??''}"></div><div class="field"><label>Janela envio: fim</label><input name="submitWindowEndDay" type="number" min="1" max="31" value="${c.submitWindowEndDay??''}"></div><div class="field"><label>NF até dia</label><input name="invoiceDeadlineDay" type="number" min="1" max="31" value="${c.invoiceDeadlineDay??''}"></div><div class="field"><label>Pagamento dia</label><input name="paymentDay" type="number" min="1" max="31" value="${c.paymentDay??''}"></div><div class="field"><label>Pagamento em quantos meses</label><input name="paymentMonthOffset" type="number" min="0" max="3" value="${c.paymentMonthOffset??0}"></div></div></div>`}
window.addBillingCycleRow=()=>{$('billingCyclesEditor').insertAdjacentHTML('beforeend',billingCycleRow({},$('billingCyclesEditor').children.length))};
window.approveBillingProfile=async groupId=>{const p=(billingCache.profiles||[]).find(x=>x.groupId===groupId);if(!p)return;if(!confirm('Aprovar esta regra financeira? Depois disso os chamados concluídos poderão gerar valores e vencimentos automaticamente.'))return;await api('/api/worker/billing',{method:'POST',body:JSON.stringify({action:'approve_profile',profile:p})});await loadBillingFinance();await loadManagement()};
window.billingBatchAction=async(batchId,action)=>{let amount=null;if(action==='received'){const b=(billingCache.batches||[]).find(x=>x.id===batchId);const value=prompt('Valor recebido',String(b?.totalAmount||0));if(value===null)return;amount=Number(String(value).replace(',','.'))||0}await api('/api/worker/billing',{method:'POST',body:JSON.stringify({action,batchId,amount})});await loadBillingFinance();await loadManagement()};
window.downloadBillingBatch=async batchId=>{const u=new URL('/api/worker/billing/export',location.origin);u.searchParams.set('companyId',activeCompanyId);u.searchParams.set('batchId',batchId);const r=await fetch(u,{headers:{'x-botguincho-company-id':activeCompanyId,...(tenantAccessToken?{authorization:`Bearer ${tenantAccessToken}`}:{})}});if(!r.ok){alert('Não foi possível gerar a planilha.');return}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fechamento.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};

function ensureBillingFinanceUI(){
  if($('billingFinanceConfig'))return;const page=$('finance');if(!page)return;
  page.insertAdjacentHTML('beforeend',`<div id="billingFinanceConfig" class="section"><div class="card"><div class="head"><div><h3>Importar planilhas antigas</h3><p>Suba fechamentos de meses anteriores e vincule cada arquivo à transportadora/grupo correto.</p></div><span class="tag green">Excel .xlsx</span></div><div class="grid2 section"><div class="field"><label>Planilhas</label><input id="historicalSpreadsheetFiles" type="file" accept=".xlsx,.xls" multiple></div><div class="field"><label>Situação padrão dos valores</label><select id="historicalReceiptDefault"><option value="received">Já recebidos</option><option value="receivable">Ainda a receber</option></select></div></div><div class="actions section"><button class="btn" id="analyzeHistoricalSpreadsheets">Analisar planilhas</button><button class="btn secondary" id="importHistoricalSpreadsheets" style="display:none">Confirmar importação</button></div><div id="historicalImportNotice" class="notice section" style="display:none"></div><div id="historicalImportPreview" class="section"></div><div id="historicalImportsHistory" class="section"></div></div><div class="card section"><div class="head"><div><h3>Financeiro por transportadora/grupo</h3><p>Valores a receber, prazos de envio, nota fiscal e pagamento separados por empresa.</p></div><button class="btn secondary" id="refreshBilling">Atualizar</button></div><div id="insurerFinanceSummary" class="grid2 section"></div></div><div class="card section"><div class="head"><div><h3>Regras de cada transportadora/grupo</h3><p>Configure o calendário e a quilometragem de cada grupo.</p></div></div><div class="notice warn section">O calendário só automatiza recebimentos depois de ser revisado e aprovado para aquela transportadora/grupo.</div><div id="billingProfilesList" class="grid2 section"></div></div><div class="card section"><div class="head"><div><h3>Fechamentos e pagamentos das transportadoras</h3><p>Corridas agrupadas automaticamente por transportadora/grupo e período.</p></div></div><div class="table-wrap section"><table class="table"><thead><tr><th>Transportadora/grupo</th><th>Período</th><th>Corridas/KM</th><th>A receber</th><th>Enviar planilha</th><th>Enviar NF</th><th>Pagamento</th><th>Status</th><th></th></tr></thead><tbody id="billingBatchesTable"></tbody></table></div></div><div class="card section"><div class="head"><div><h3>Pagamento do motorista</h3><p>Fechamento mensal do dia 20 anterior até o dia 20 atual.</p></div><span class="tag green">Pagamento dia 20</span></div><div class="grid2 section"><div class="notice good"><b>Até 50 km</b><br>R$ 40,00 por corrida</div><div class="notice good"><b>Acima de 50 km</b><br>R$ 40,00 + R$ 0,70 por km excedente</div></div><div class="notice warn section">Toda hora trabalhada cobrada no atendimento pertence integralmente ao motorista.</div><div class="table-wrap section"><table class="table"><thead><tr><th>Motorista</th><th>Período</th><th>Corridas/KM</th><th>Corridas</th><th>Horas trabalhadas</th><th>Total</th><th>Vencimento</th><th>Status</th><th></th></tr></thead><tbody id="driverPayrollTable"></tbody></table></div></div></div>`);$('refreshBilling').onclick=loadBillingFinance;$('analyzeHistoricalSpreadsheets').onclick=analyzeHistoricalSpreadsheets;$('importHistoricalSpreadsheets').onclick=importHistoricalSpreadsheets;
}

function renderBillingFinance(){
  const profiles=billingCache.profiles||[],batches=billingCache.batches||[],summaries=billingCache.insurerSummaries||[],payrolls=billingCache.driverPayrolls||[];
  $('insurerFinanceSummary').innerHTML=summaries.length?summaries.map(s=>`<div class="card"><div class="head"><div><h3>${esc(s.groupName||'Seguradora')}</h3><p>${s.callCount||0} corridas faturadas</p></div>${tag(s.profileStatus==='approved'?'Aprovada':'Revisar regra')}</div><div class="kpi-line"><span>Valor a receber</span><b class="money pos">${money(s.receivable)}</b></div><div class="kpi-line"><span>Em atraso</span><b class="${Number(s.overdue)>0?'money neg':''}">${money(s.overdue)}</b></div><div class="kpi-line"><span>Já recebido</span><b>${money(s.received)}</b></div><div class="kpi-line"><span>Planilha até</span><b>${date(s.nextStatementDue)}</b></div><div class="kpi-line"><span>Nota fiscal até</span><b>${date(s.nextInvoiceDue)}</b></div><div class="kpi-line"><span>Previsão de receber</span><b>${date(s.nextPaymentDue)}</b></div><div class="small section">${s.openClosings||0} fechamento(s) em aberto</div></div>`).join(''):'<div class="empty">Nenhuma seguradora com movimento financeiro.</div>';
  $('billingProfilesList').innerHTML=profiles.length?profiles.map(p=>`<div class="card"><div class="head"><div><h3>${esc(p.groupName||'Grupo')}</h3><p>${esc(billingModeLabel[p.paymentMode]||p.paymentMode)}</p></div>${tag(p.status==='approved'?'Aprovado':'Revisar')}</div><div class="small">Rota: ${p.routeBasis==='truck_origin_destination_base'?'Caminhão → origem → destino → base':esc(p.routeBasis)}</div>${p.sourceNote?`<p class="muted section">${esc(p.sourceNote)}</p>`:''}<div class="actions section"><button class="btn secondary small" onclick="editBillingProfile('${p.groupId}')">Configurar</button>${p.status!=='approved'?`<button class="btn small" onclick="approveBillingProfile('${p.groupId}')">Aprovar</button>`:''}</div></div>`).join(''):'<div class="empty">Os grupos aparecerão aqui depois de sincronizados.</div>';
  $('billingBatchesTable').innerHTML=batches.length?batches.map(b=>`<tr><td><b>${esc(b.groupName||'Seguradora')}</b></td><td>${date(b.periodStart)}<br><span class="muted">até ${date(b.periodEnd)}</span></td><td>${b.callCount||0} corridas<br><span class="muted">${Number(b.totalKm||0).toLocaleString('pt-BR')} km</span></td><td>${money(b.totalAmount)}</td><td>${date(b.statementDue)}</td><td>${date(b.invoiceDue)}</td><td>${date(b.paymentDue)}</td><td>${tag(String(b.status||'accumulating').replaceAll('_',' '))}</td><td><div class="actions"><button class="btn ghost small" onclick="downloadBillingBatch('${b.id}')">Planilha</button>${!b.statementSentAt?`<button class="btn ghost small" onclick="billingBatchAction('${b.id}','statement_sent')">Planilha enviada</button>`:''}${b.statementSentAt&&!b.invoiceSentAt?`<button class="btn ghost small" onclick="billingBatchAction('${b.id}','invoice_sent')">NF enviada</button>`:''}${b.status!=='received'?`<button class="btn small" onclick="billingBatchAction('${b.id}','received')">Recebido</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="9">Nenhum fechamento criado ainda.</td></tr>';
  $('driverPayrollTable').innerHTML=payrolls.length?payrolls.map(p=>`<tr><td><b>${esc(p.driverName||'Motorista')}</b></td><td>${date(p.periodStart)}<br><span class="muted">até ${date(p.periodEnd)}</span></td><td>${p.callCount||0} corridas<br><span class="muted">${Number(p.totalKm||0).toLocaleString('pt-BR')} km</span></td><td>${money(p.routeAmount)}</td><td>${money(p.workedTimeAmount)}</td><td><b>${money(p.totalAmount)}</b></td><td>${date(p.paymentDue)}</td><td>${tag(String(p.status||'accumulating').replaceAll('_',' '))}</td><td><div class="actions"><button class="btn ghost small" onclick="downloadDriverPayroll('${p.id}')">Planilha</button>${p.status==='paid'?`<span class="small">Pago em ${date(p.paidAt)}</span>`:`<button class="btn small" onclick="driverPayrollPaid('${p.id}')">Marcar pago</button>`}</div></td></tr>`).join(''):'<tr><td colspan="9">Nenhum pagamento de motorista calculado ainda.</td></tr>';
  renderHistoricalImportsHistory();
}

let historicalImportDrafts=[];
const normalizedImportName=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const fileBase64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').split(',')[1]||'');reader.onerror=()=>reject(reader.error||new Error('Falha ao ler arquivo'));reader.readAsDataURL(file)});
function closestTransporter(preview){const profiles=billingCache.profiles||[],needles=[preview.detectedTransporter,preview.sheetName].map(normalizedImportName).filter(Boolean);return profiles.find(p=>needles.some(n=>{const name=normalizedImportName(p.groupName);return name===n||name.includes(n)||n.includes(name)}))||null}
function renderHistoricalImportDrafts(){const box=$('historicalImportPreview');if(!box)return;const profiles=billingCache.profiles||[];box.innerHTML=historicalImportDrafts.length?historicalImportDrafts.map((item,index)=>{const selected=item.groupId||closestTransporter(item.preview)?.groupId||'';item.groupId=selected;const opts=profiles.map(p=>`<option value="${esc(p.groupId)}" ${selected===p.groupId?'selected':''}>${esc(p.groupName||'Grupo')}</option>`).join('');return`<div class="card section"><div class="head"><div><b>${esc(item.fileName)}</b><p>${esc(item.preview.detectedTransporter||item.preview.sheetName)} · ${date(item.preview.periodStart)} a ${date(item.preview.periodEnd)}</p></div>${tag(item.error?'Erro':'Pronta')}</div>${item.error?`<div class="notice bad">${esc(item.error)}</div>`:`<div class="grid2"><div class="field"><label>Transportadora/grupo correspondente</label><select onchange="historicalDraftGroup(${index},this.value)"><option value="">Selecione</option>${opts}</select></div><div class="field"><label>Situação do fechamento</label><select onchange="historicalDraftReceipt(${index},this.value)"><option value="received" ${item.receiptStatus==='received'?'selected':''}>Já recebido</option><option value="receivable" ${item.receiptStatus==='receivable'?'selected':''}>Ainda a receber</option></select></div></div><div class="kpi-line"><span>Corridas encontradas</span><b>${item.preview.totals.calls}</b></div><div class="kpi-line"><span>KM total</span><b>${Number(item.preview.totals.km||0).toLocaleString('pt-BR')} km</b></div><div class="kpi-line"><span>Valor total</span><b>${money(item.preview.totals.amount)}</b></div><div class="small section">A planilha será registrada como enviada para a transportadora selecionada.</div>`}</div>`}).join(''):'<div class="empty">Selecione as planilhas para visualizar a importação.</div>';$('importHistoricalSpreadsheets').style.display=historicalImportDrafts.some(x=>!x.error)?'inline-flex':'none'}
window.historicalDraftGroup=(index,value)=>{historicalImportDrafts[index].groupId=value};window.historicalDraftReceipt=(index,value)=>{historicalImportDrafts[index].receiptStatus=value};
async function analyzeHistoricalSpreadsheets(){const files=[...($('historicalSpreadsheetFiles')?.files||[])];const notice=$('historicalImportNotice');if(!files.length){notice.style.display='block';notice.className='notice bad section';notice.textContent='Selecione pelo menos uma planilha Excel.';return}notice.style.display='block';notice.className='notice warn section';notice.textContent='Analisando planilhas...';historicalImportDrafts=[];for(const file of files){try{const base64=await fileBase64(file);const data=await api('/api/worker/billing/import-preview',{method:'POST',body:JSON.stringify({fileName:file.name,base64})});const receiptStatus=$('historicalReceiptDefault').value;historicalImportDrafts.push({fileName:file.name,preview:data.preview,receiptStatus,groupId:''})}catch(error){historicalImportDrafts.push({fileName:file.name,error:error.message,preview:{}})}}renderHistoricalImportDrafts();notice.className='notice good section';notice.textContent=`${historicalImportDrafts.filter(x=>!x.error).length} planilha(s) analisada(s). Confira a transportadora de cada arquivo antes de confirmar.`}
async function importHistoricalSpreadsheets(){const valid=historicalImportDrafts.filter(x=>!x.error);if(valid.some(x=>!x.groupId)){alert('Selecione a transportadora/grupo de todas as planilhas.');return}const profiles=billingCache.profiles||[],notice=$('historicalImportNotice');notice.style.display='block';notice.className='notice warn section';notice.textContent='Importando históricos...';let imported=0,duplicates=0;for(const item of valid){const profile=profiles.find(p=>p.groupId===item.groupId);const data=await api('/api/worker/billing',{method:'POST',body:JSON.stringify({action:'import_history',fileName:item.fileName,groupId:item.groupId,groupName:profile?.groupName||item.preview.detectedTransporter,records:item.preview.records,receiptStatus:item.receiptStatus})});imported+=Number(data.result?.imported||0);duplicates+=Number(data.result?.duplicates||0)}historicalImportDrafts=[];$('historicalSpreadsheetFiles').value='';renderHistoricalImportDrafts();notice.className='notice good section';notice.textContent=`Importação concluída: ${imported} corrida(s) registrada(s)${duplicates?` e ${duplicates} duplicada(s) ignorada(s)`:''}.`;await loadBillingFinance();await loadManagement()}
function renderHistoricalImportsHistory(){const box=$('historicalImportsHistory');if(!box)return;const imports=billingCache.historicalImports||[];box.innerHTML=imports.length?`<h4>Importações realizadas</h4><div class="table-wrap section"><table class="table"><thead><tr><th>Arquivo</th><th>Transportadora/grupo</th><th>Período</th><th>Corridas</th><th>KM</th><th>Valor</th><th>Situação</th></tr></thead><tbody>${imports.map(item=>`<tr><td>${esc(item.fileName)}</td><td><b>${esc(item.groupName)}</b></td><td>${date(item.periodStart)} a ${date(item.periodEnd)}</td><td>${item.callCount||0}</td><td>${Number(item.totalKm||0).toLocaleString('pt-BR')}</td><td>${money(item.totalAmount)}</td><td>${tag(item.receiptStatus==='received'?'Recebido':'A receber')}</td></tr>`).join('')}</tbody></table></div>`:''}

window.driverPayrollPaid=async payrollId=>{const p=(billingCache.driverPayrolls||[]).find(x=>x.id===payrollId);if(!p)return;const value=prompt('Valor pago ao motorista',String(p.totalAmount||0));if(value===null)return;await api('/api/worker/billing',{method:'POST',body:JSON.stringify({action:'driver_paid',payrollId,amount:Number(String(value).replace(',','.'))||0})});await loadBillingFinance();await loadManagement()};
window.downloadDriverPayroll=async payrollId=>{const u=new URL('/api/worker/billing/driver-export',location.origin);u.searchParams.set('companyId',activeCompanyId);u.searchParams.set('payrollId',payrollId);const r=await fetch(u,{headers:{'x-botguincho-company-id':activeCompanyId,...(tenantAccessToken?{authorization:`Bearer ${tenantAccessToken}`}:{})}});if(!r.ok){alert('Não foi possível gerar a planilha do motorista.');return}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pagamento-motorista.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
